		invsc.Guid AS InvoiceScheduleId
FROM   [SFin].[InvoiceScheduleMonthConfiguration] AS root_hobt
JOIN   [SFin].[InvoiceSchedules] AS invsc ON (invsc.ID = root_hobt.InvoiceScheduleId)' WHERE ID = 368
UPDATE SCore.EntityQueries SET Statement = N'EXEC [SFin].[InvoiceScheduleMonthConfigurationDelete]  
	@Guid = @Guid' WHERE ID = 388

