UPDATE SUserInterface.DropDownListDefinitions SET SqlQuery = N'SELECT  olfu.Label AS Name,
        root_hobt.Guid
FROM    SUserInterface.GridViewDefinitions root_hobt
OUTER APPLY	SCore.ObjectLabelForUser(root_hobt.LanguageLabelId,[[UserId]]) olfu
WHERE root_hobt.Guid = [[ParentGuid]]' WHERE ID = 13
UPDATE SUserInterface.DropDownListDefinitions SET SqlQuery = N'SELECT	
		root_hobt.Guid,
		root_hobt.Name
FROM	SFin.CreditTerms root_hobt', DetailPageUrl = N'DynamicEdit', IsDetailWindowed = 1, EntityTypeId = 96, InformationPageUrl = N'DynamicEdit' WHERE ID = 69
UPDATE SUserInterface.DropDownListDefinitions SET SqlQuery = N'SELECT	root_hobt.Guid,
		root_hobt.Name
FROM	SJob.JobPaymentStages_List root_hobt
JOIN	SJob.Jobs			AS j ON (j.ID	= root_hobt.JobID)
JOIN	SFin.Transactions	AS t ON (t.JobID = j.ID)
WHERE	(t.Guid = ''[[ParentGuid]]'')
	AND (root_hobt.RowStatus NOT IN (0, 254))', DetailPageUrl = N'DynamicEdit', IsDetailWindowed = 1, InformationPageUrl = N'DynamicEdit' WHERE ID = 76
UPDATE SUserInterface.DropDownListDefinitions SET SqlQuery = N'SELECT 
    root_hobt.Guid,
    root_hobt.FullName AS Name
FROM SCore.Identities AS root_hobt
WHERE root_hobt.OriganisationalUnitId = (
    SELECT OriganisationalUnitId
    FROM SCore.Identities
    WHERE ID = [[UserId]]
)
AND root_hobt.IsActive = 1' WHERE ID = 112

